head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > P > ignoreChar]<br/>SearchBox 입력이 불가능한 문자의 집합을 정규식의 문자클래스 형식으로 설정합니다.",
    "validation" : [
        "ignoreChar 속성으로 SearchBox 컴포넌트에서 입력이 불가능한 문자 패턴을 설정할 수 있어야 합니다.",
        "allowChar 속성에 같은 문자가 설정되어도 해당 문자는 입력 되지 않아야 합니다.",
        "ignoreChar 속성값은 정규식의 문자클래스 형식으로 입력이 불가능한 문자 집합을 설정합니다.",
        "정규식의 문자클래스에서 특수문자로 처리되는 ']', '-', '\\' 등의 문자는 이스케이프 처리하여 설정해야 합니다.",
        "설정값은 정규식의 문자클래스('[...]' 처리)에 반영되어 입력이 불가능한 문자를 찾는데 사용됩니다.",
        "validate() 메소드 실행 시 입력값에 ignoreChar 속성에 설정된 문자가 포함되면 유효성 체크는 실패로 처리되어야 합니다.",
        "validate() 실패 시 displaymessage='true' 이면 시스템 기본 메시지 '허용되지 않은 문자열은 {속성값} 입니다.' 가 출력됩니다.",
        "validate() 실패 메시지는 invalidMessage 또는 invalidMessageFunc 속성으로 변경할 수 있습니다.",
        "validate() 시 allowChar 속성 체크 후 ignoreChar 의 유효성 체크가 실행됩니다.",
        "한글과 같은 다국어 문자와 붙여넣기로 입력된 값은 컴포넌트에서 포커스가 해제될 때 처리됩니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function(target) {
    let rtn = target.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);
}

scwin.check_validate = function (target) {
    let rtn = target.validate();

    if (rtn)
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : PASS");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : FAIL");
}

let strValue = "azAZ123가나다~!@#$%^&*()_+-=\\[]{},./;':\"";


// target1 : ignoreChar=0-9
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue(strValue);
    target1.focus();
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text(target1);
}

// target2 : ignoreChar=a-z
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue(strValue);
    target2.focus();
};

scwin.btn_getText2_onclick = function (e) {
    scwin.get_text(target2);
}

// target3 : ignoreChar=A-Z
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue(strValue);
    target3.focus();
};

scwin.btn_getText3_onclick = function (e) {
    scwin.get_text(target3);
}

// target4 : ignoreChar=특수문자 (이스케이프 포함)
scwin.btn_setValue4_onclick = function (e) {
    target4.setValue(strValue);
    target4.focus();
};

scwin.btn_getText4_onclick = function (e) {
    scwin.get_text(target4);
}

// target5 : allowChar=0-9 + ignoreChar=0-9 (같은 문자 입력 불가)
scwin.btn_setValue5_onclick = function (e) {
    target5.setValue(strValue);
    target5.focus();
};

scwin.btn_getText5_onclick = function (e) {
    scwin.get_text(target5);
}

// target6 : 붙여넣기 (포커스 해제 시 처리)
scwin.btn_getText6_onclick = function (e) {
    scwin.get_text(target6);
}

// target7 : validate, displaymessage=true 기본 메시지 + allowChar 체크 후 ignoreChar
scwin.btn_setValue7_onclick = function (e) {
    target7.setValue("123");
};

scwin.btn_validate7_onclick = function (e) {
    scwin.check_validate(target7);
}

// target8 : validate, invalidMessage 로 메시지 변경
scwin.btn_setValue8_onclick = function (e) {
    target8.setValue("123");
};

scwin.btn_validate8_onclick = function (e) {
    scwin.check_validate(target8);
}


scwin.btn_setAll_onclick = function (e) {
    for (var i = 1; i <= 8; i ++) {
        if (i !== 6 && i !== 7 && i !== 8)
            eval("scwin.btn_setValue"+i+"_onclick()");
    }
}

scwin.btn_getAll_onclick = function (e) {
    for (var i = 1; i <= 8; i ++) {
        if (i !== 7 && i !== 8)
            eval("scwin.btn_getText"+i+"_onclick()");
    }
};
